sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (newValue === '') {
      return;
   }

	var ga = new GlideAjax("CouseScheduleAjaxUtils");
	var splitedDate = g_form.getValue("date").toString().split("/");
	var formatedDate = splitedDate[2] + "-" + splitedDate[1] + "-"  + splitedDate[0];
	var encodedQuery = "dateON" + formatedDate + "@javascript:gs.dateGenerate('" + formatedDate +"','start')@javascript:gs.dateGenerate('" + formatedDate + "','end')^course.sys_id=" +g_form.getValue("course").toString();
	ga.addParam("sysparm_encoded_query", encodedQuery);
	ga.addParam("sysparm_name", "getEncodedQuery");

	ga.getXML(function (response){
		var answer = response.responseXML.documentElement.getAttribute("answer");
		var list = JSON.parse(answer);
		if(list.length > 0){
			g_form.addErrorMessage("This course is already schedule to this day");
			g_form.setValue("date", "");
		}else{
			g_form.clearMessages();
		}
	});


}
